}): JSX.Element {
  const { clause, title, description, values, placeholder, onAdd, onRemove, onChange, addLabel, accentClass, animDelay } = props;

  return (
    <Card
      className={cn(
        'policy-fade-up border-border/50 bg-card/80 backdrop-blur-sm',
